contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0) && newOwner != address(0), "zero address not meaningful");

        address initialOwner = c.owner();

        // Try to set the new owner.  Because msg.sender of this test contract is the
        // deployer of c, the call will succeed exactly when `caller` is the deployer.
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address finalOwner = c.owner();

        // General rule: only the admin (the deployer) can change the owner.
        // If the external call did not revert, the owner must now be newOwner;
        // if it reverted, the owner must still be the initial owner.
        if (!reverted) {
            assert(finalOwner == newOwner);
        } else {
            assert(finalOwner == initialOwner);
        }
    }

    receive() external payable {}
}

